You are a formal verification assistant. The following Dafny program fails Dafny verification.

=== PROGRAM ===
type T = int // for demo purposes, but could be another type
predicate sorted(a: array<T>, n: nat) 
    requires n <= (a.Length) + 1
    reads a
{
    forall i,j :: 0 <= i < j < n ==> a[i] <= a[j]
}

// Use binary search to find an appropriate position to insert a value 'x'
// in a sorted array 'a', so that it remains sorted.
method binarySearch(a: array<T>, x: T) returns (index: int) 
    requires sorted(a, a.Length)
    ensures sorted(a, a.Length)
    //ensures a[..] == old(a)[..]
    ensures 0 <= index <= a.Length
    //ensures forall i :: 0 <= i < index ==> a[i] <= x
    //ensures forall i :: index <= i < a.Length ==> a[i] >= x

    ensures index > 0 ==> a[index-1] <= x
    ensures index < a.Length ==> a[index] >= x
{
    var low, high := 0, a.Length;
    while low < high 
        decreases high-low
        invariant 0 <= low <= high <= a.Length
        invariant low > 0 ==> a[low-1] <= x
        invariant high < a.Length ==> a[high] >= x

    {
        var mid := low + (high - low) / 2;
        if {
            case a[mid] < x => low := mid + 1;
            case a[mid] > x => high := mid;
            case a[mid] == x => return mid;
        }
    }
    return low;
}

// Simple test cases to check the post-condition
method testBinarySearch() {
    var a := new int[2] [1, 3];
    var id0 := binarySearch(a, 0);
    assert id0 == 0;
    var id1 := binarySearch(a, 1);
    assert id1 in {0, 1};
    var id2 := binarySearch(a, 2);
    assert id2 == 1;
    var id3 := binarySearch(a, 3);
    assert id3 in {1, 2};
    var id4 := binarySearch(a, 4);
    assert id4 == 2;
}

=== DAFNY ERROR ===
program.dfy(6,46): Error: index out of range

Dafny program verifier finished with 3 verified, 1 error

=== COUNTEREXAMPLE ===
At initial state: a.Length = 7720, n = 7721.

Analyze the failure and respond with ONLY a valid JSON object — no explanation, no markdown, no code fences. Use exactly this structure:

{
  "spec_element": "<one of: requires | invariant | ensures>",
  "proof_obligation": "<one of: initiation | preservation | bridge>",
  "diagnosis": "<explanation of what broke and why>",
  "repair": "<the corrected Dafny specification line that restores the intended behavior>"
}

Definitions:
- requires: the precondition that must hold before the method executes
- invariant: the loop invariant that must hold throughout the loop
- ensures: the postcondition that the method must guarantee on return
- initiation: the precondition does not establish the invariant at loop entry
- preservation: the loop body does not maintain the invariant
- bridge: the invariant and loop exit condition do not imply the postcondition

